	@Test
	void volatileScalarRemainsAnOrdinaryPerInvocationEffect() {
		AlternatingFunction function = new AlternatingFunction();
		FunctionRegistry registry = FunctionRegistry.getInstance();
		var previous = registry.get(function.getURI());
		registry.add(function);
		try {
			TupleExpr body = new Filter(q10Body(), new FunctionCall(function.getURI(), Var.of("code")));
			List<BindingSet> frames = List.of(binding("patient", P0), binding("patient", P0), binding("patient", P0),
					binding("patient", P0));
			List<Boolean> ordinary = reference(body, frames, ConditionBindingScope.ALL, false, medications());
			assertEquals(List.of(true, false, true, false), ordinary);
			assertEquals(4, function.calls.get());
			function.calls.set(0);
			Source source = medications();
			Filter filter = outer(body, false, ConditionBindingScope.ALL);
			Mode.MATERIALIZED.configure(filter);
			assertEquals(ordinary, evaluate(new CountingStrategy(source).precompile(filter), frames));
			assertEquals(4, function.calls.get(), "A volatile per-probe result must not be memoized or built once");
			source.assertClosed();
		} finally {
			registry.remove(function);
			previous.ifPresent(registry::add);
		}
	}

	@ParameterizedTest(name = "{0}, preparer={1}")
	@MethodSource("representationPreparationCases")
	void directBoundProbeAndUncorrelatedBuildRequireSeparateProofs(Representative kind, Preparation preparation) {
		Value caller = kind.caller();
		Value stored = kind.stored();
		BindingSet frame = binding("x", caller);
		assertTrue(reference(kind.body(), List.of(frame), ConditionBindingScope.ALL, false,
				new Source(List.of(VF.createStatement(S, VALUE, stored)), preparation, caller, stored)).getFirst());
		Exists fixedHolder = new Exists(kind.body());
		BindingAssignerOptimizer.substituteInScope(fixedHolder.getSubQuery(), frame);
		Filter fixedFilter = (Filter) fixedHolder.getSubQuery();
		Var fixedTerm = ((StatementPattern) fixedFilter.getArg()).getObjectVar();
		Var fixedScalar = (Var) ((UnaryValueOperator) ((Compare) fixedFilter.getCondition()).getLeftArg()).getArg();
		assertSame(caller, fixedTerm.getValue());
		assertSame(caller, fixedScalar.getValue());
		Source fixedSource = new Source(List.of(VF.createStatement(S, VALUE, stored)), preparation, caller, stored);
		DefaultEvaluationStrategy fixedStrategy = new DefaultEvaluationStrategy(fixedSource, null);
		QueryEvaluationStep fixed = fixedStrategy.precompileRuntimeSubtree(fixedFilter, context());
		try (CloseableIteration<BindingSet> rows = fixed.evaluate(frame)) {
			assertTrue(rows.hasNext(), "Lookup preparation does not replace the already substituted scalar Var");
		}
		fixedSource.assertClosed();
		assertSame(caller, fixedTerm.getValue(), "The lookup normalization owns a copy of the query term");
		assertSame(caller, fixedScalar.getValue());
		if (preparation != Preparation.NONE) {
			assertTrue(fixedSource.callerPreparations.get() > 0, "Fixed-value lookup preparation actually ran");
		}
		Source directSource = new Source(List.of(VF.createStatement(S, VALUE, stored)), preparation, caller, stored);
		DefaultEvaluationStrategy direct = new DefaultEvaluationStrategy(directSource, null);
		Exists directHolder = new Exists(kind.body());
		QueryEvaluationStep prepared = direct.precompileRuntimeSubtree(directHolder.getSubQuery(), context());
		boolean bound;
		try (CloseableIteration<BindingSet> rows = prepared.evaluate(frame)) {
			bound = rows.hasNext();
		}
		assertEquals(preparation != Preparation.CANONICAL, bound,
				"A real preparer can change the scalar observation before a directly compiled filter reads x");
		if (preparation != Preparation.NONE) {
			assertTrue(directSource.callerPreparations.get() > 0, "The actual bound-value preparation hook ran");
		}
		directSource.assertClosed();

		Source buildSource = new Source(List.of(VF.createStatement(S, VALUE, stored)), preparation, caller, stored);
		DefaultEvaluationStrategy build = new DefaultEvaluationStrategy(buildSource, null);
		Exists buildHolder = new Exists(kind.body());
		QueryEvaluationStep uncorrelated = build.precompileRuntimeSubtree(buildHolder.getSubQuery(), context());
		try (CloseableIteration<BindingSet> rows = uncorrelated.evaluate(EmptyBindingSet.getInstance())) {
			assertFalse(rows.hasNext(),
					"An uncorrelated build observes the stored spelling even without any preparer");
		}
		buildSource.assertClosed();
	}

	@ParameterizedTest(name = "supplied={0}, retained={1}, negated={2}")
	@MethodSource("graphCases")
	void actualGraphAuthorityAndRetainedScopeSurviveTheProbe(boolean supplied, boolean retained, boolean negated) {
		QueryBindingSet raw = binding("callerGraph", G2);
		raw.setBinding("privateGraph", G1);
		raw.setBinding("outputOnly", HIT);
		BindingSet frame = supplied ? GraphFrameBindings.supply(raw, "privateGraph", G1) : raw;
		frame = BindingSetOrigin.requestInput(frame);
		assertEquals(supplied, GraphFrameBindings.isSupplied(frame, "privateGraph"));
		Filter guard = new Filter(new SingletonSet(),
				new SameTerm(Var.of("privateGraph"), new ValueConstant(G1)));
		guard.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(guard, new ProjectionElemList(), true);
		projection.setProjectionContext(Var.of("callerGraph"));
		projection.setInheritedGraphParameter("privateGraph");
		ConditionBindingScope scope = ConditionBindingScope.retain(retained ? Set.of("privateGraph") : Set.of());
		List<Boolean> ordinary = reference(projection, List.of(frame), scope, negated, new Source(List.of()));
		assertEquals(List.of((supplied && retained) != negated), ordinary);
		Source source = new Source(List.of());
		Filter filter = outer(projection, negated, scope);
		assertEquals(ordinary, evaluate(new CountingStrategy(source).precompile(filter), List.of(frame)));
		source.assertClosed();
		assertEquals(supplied, GraphFrameBindings.isSupplied(frame, "privateGraph"));
	}

